import {analyze,scenarios} from './engine.js';
const $=id=>document.getElementById(id);
const state={active:false,index:0,signals:[],score:0,count:0,l2:0,timer:null,toastTimer:null,threshold:55,notifications:0,feedback:0};
const labels={live:'即時守護',family:'家人守護',privacy:'隱私與設定',architecture:'系統架構'};
for(const [key,scenario] of Object.entries(scenarios)){const option=document.createElement('option');option.value=key;option.textContent=scenario.name;$('scenario').append(option);}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function changeView(view){document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==`view-${view}`);document.querySelectorAll('.nav').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-current',el.dataset.view===view?'page':'false');});$('page-title').textContent=labels[view];}
document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',()=>changeView(button.dataset.view)));
function stopTimer(){clearInterval(state.timer);state.timer=null;}
function syncTimer(){stopTimer();if(state.active&&$('auto').checked&&state.index<scenarios[$('scenario').value].lines.length)state.timer=setInterval(next,4000);}
function caller(){const s=scenarios[$('scenario').value];$('caller').textContent=s.caller;$('number').textContent=s.number;}
function reset(){stopTimer();Object.assign(state,{active:false,index:0,signals:[],score:0,count:0,l2:0});$('transcript').replaceChildren();const empty=document.createElement('p');empty.className='empty';empty.textContent='本次對話已清除。選擇情境，重新啟用守護。';$('transcript').append(empty);$('score').textContent='0';$('meter-fill').style.width='0';$('meter-fill').style.background='#93b368';$('risk-label').textContent='待機中';$('warning').hidden=true;$('reasons').replaceChildren();$('reasons').textContent='尚未偵測到風險訊號';$('clock').textContent='00:00';$('call-status').textContent='等待啟用守護';$('phone-message').textContent='開啟守護，開始體驗即時判斷';$('l1-status').textContent='待機';$('l2-status').textContent='待機';$('sentences').textContent='0';$('activations').textContent='0';$('latency').textContent='—';$('start').disabled=false;$('scenario').disabled=false;for(const id of ['next','end','custom','send'])$(id).disabled=true;$('custom').value='';document.body.classList.remove('running');}
function process(text,time='自訂'){
 if(!state.active)return;const t=performance.now();const result=analyze(text,state.signals,state.threshold);const duration=performance.now()-t;state.signals=result.signals;state.score=result.score;state.count++;if(result.l2)state.l2++;
 if(state.count===1)$('transcript').replaceChildren();
 const row=document.createElement('div');row.className='utterance';const timestamp=document.createElement('time');timestamp.textContent=time;const message=document.createElement('p');message.textContent=text;const sub=document.createElement('small');sub.textContent=result.hits.length?result.hits.map(r=>r.label).join(' · '):result.safety?'辨識為防詐提醒，未加入風險訊號':'未命中本次風險規則';message.append(sub);row.append(timestamp,message);$('transcript').append(row);while($('transcript').children.length>50)$('transcript').firstChild.remove();$('transcript').scrollTop=$('transcript').scrollHeight;
 $('score').textContent=result.score;$('meter-fill').style.width=`${result.score}%`;$('meter-fill').style.background=result.level==='high'?'#c1714c':result.level==='medium'?'#c5a65d':'#93b368';$('risk-label').textContent={high:'高風險・建議查證',medium:'需留意・持續觀察',low:'低風險・持續守護'}[result.level];$('warning').hidden=result.level!=='high';$('warning-reason').textContent='本次出現：'+result.reasons.join('、')+'。先暫停提供資料或操作，另行查證對方身分。';$('reasons').replaceChildren();for(const reason of result.reasons){const tag=document.createElement('span');tag.textContent=reason;$('reasons').append(tag);}if(!result.reasons.length)$('reasons').textContent='尚未偵測到風險訊號；不代表一定安全';$('sentences').textContent=state.count;$('activations').textContent=state.l2;$('latency').textContent=duration.toFixed(2);$('l1-status').textContent='本機檢查中';$('l2-status').textContent=result.l2?'已啟動（示範）':'待命・節省運算';$('phone-message').textContent=result.level==='high'?'已提醒・通話仍由你掌握':'守護中・只分析，不錄音';$('clock').textContent=time==='自訂'?$('clock').textContent:time;
}
function next(){if(!state.active)return;const lines=scenarios[$('scenario').value].lines;if(state.index>=lines.length){stopTimer();return;}const [time,text]=lines[state.index++];process(text,time);if(state.index===lines.length){$('next').disabled=true;stopTimer();toast('情境播放完畢，可輸入新話術或結束通話。');}}
$('start').addEventListener('click',()=>{if(!$('consent').checked){toast('請先勾選本次分析同意。');$('consent').focus();return;}reset();state.active=true;$('start').disabled=true;$('scenario').disabled=true;for(const id of ['next','end','custom','send'])$(id).disabled=false;$('call-status').textContent='模擬通話中 · 守護已啟用';document.body.classList.add('running');next();syncTimer();});
$('next').addEventListener('click',next);$('auto').addEventListener('change',syncTimer);$('end').addEventListener('click',()=>{reset();$('consent').checked=false;toast('通話已結束，對話與風險脈絡已清除。');});$('consent').addEventListener('change',()=>{if(state.active&&!$('consent').checked){reset();toast('已撤回同意並清除本次對話。');}});$('scenario').addEventListener('change',()=>{reset();caller();});
$('custom-form').addEventListener('submit',event=>{event.preventDefault();const text=$('custom').value.trim();if(!text||!state.active)return;process(text);$('custom').value='';});
$('ack').addEventListener('click',()=>{$('warning').hidden=true;toast('已確認提醒；識詐通不會自動掛斷。新話術仍會重新評估。');});
function notify(test=false){if(!test&&!state.active)return;const target=$('family-name').value.trim()||'我的家人';if(state.notifications===0)$('family-notifications').replaceChildren();const card=document.createElement('div');card.className='notification';const heading=document.createElement('strong');heading.textContent=`給 ${target} 的通知預覽`;const message=document.createElement('p');message.textContent=test?'這是一則守護通知測試。未傳送任何實際訊息。':`模擬通話出現可疑訊號，展示風險指標 ${state.score}/100，請關心家人並協助查證。`;const small=document.createElement('small');small.textContent='未包含逐字稿、電話號碼或錄音 · 僅此頁面預覽';card.append(heading,message,small);$('family-notifications').prepend(card);while($('family-notifications').children.length>10)$('family-notifications').lastChild.remove();state.notifications++;toast('已建立家人通知預覽，沒有實際發送。');}
$('notify').addEventListener('click',()=>notify());$('family-test').addEventListener('click',()=>notify(true));$('false-positive').addEventListener('click',()=>{state.feedback++;$('warning').hidden=true;toast('誤判回饋已在本次記憶體記錄，未上傳；結束頁面後清除。');});
$('threshold').addEventListener('input',()=>{state.threshold=Number($('threshold').value);$('threshold-value').textContent=state.threshold;if(state.active){const result=analyze('',state.signals,state.threshold);$('warning').hidden=result.level!=='high';$('risk-label').textContent={high:'高風險・建議查證',medium:'需留意・持續觀察',low:'低風險・持續守護'}[result.level];}});
$('clear').addEventListener('click',()=>{reset();state.threshold=55;state.notifications=0;state.feedback=0;$('threshold').value=55;$('threshold-value').textContent='55';$('family-name').value='我的家人';$('family-notifications').replaceChildren();$('family-notifications').textContent='目前沒有示範通知';$('consent').checked=false;$('federated').checked=false;$('auto').checked=false;toast('本次資料與設定已清除。');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTimer();$('auto').checked=false;}});window.addEventListener('pagehide',reset);caller();
